/* ============================================================================================
   NAIA INC. · DATOS DE PRUEBA (6 meses de uso simulado en 3 universidades)
   Ejecutar DESPUÉS de dataBase_Creation.sql y storedProcedures_Script.sql, sobre una base VACÍA.
   Las fechas son relativas al día en que se ejecuta: la data siempre se ve "de ahorita".
   Contraseña de TODOS los usuarios: Clave123
   Universidades ficticias (nombres y dominios inventados para pruebas).
   ============================================================================================ */
USE NaiaInc
GO

SET NOCOUNT ON;
SET XACT_ABORT ON;

IF EXISTS (SELECT 1 FROM dbo.Institucion)
BEGIN
    RAISERROR(N'La base ya tiene universidades. Este script es para una base recién creada.', 16, 1);
    RETURN;
END

DECLARE @Hoy DATETIME2(0) = CAST(CAST(SYSDATETIME() AS DATE) AS DATETIME2(0));   -- medianoche de hoy

BEGIN TRANSACTION;

-- ---------- Universidades ----------
SET IDENTITY_INSERT dbo.Institucion ON;
SET IDENTITY_INSERT dbo.Institucion OFF;

-- ---------- Catálogos de cada universidad ----------
SET IDENTITY_INSERT dbo.Departamento ON;
SET IDENTITY_INSERT dbo.Departamento OFF;

SET IDENTITY_INSERT dbo.EquipoSoporte ON;
SET IDENTITY_INSERT dbo.EquipoSoporte OFF;

SET IDENTITY_INSERT dbo.Carrera ON;
SET IDENTITY_INSERT dbo.Carrera OFF;

SET IDENTITY_INSERT dbo.Ubicacion ON;
SET IDENTITY_INSERT dbo.Ubicacion OFF;

SET IDENTITY_INSERT dbo.Categoria ON;
SET IDENTITY_INSERT dbo.Categoria OFF;

-- ---------- Usuarios ----------
SET IDENTITY_INSERT dbo.Usuario ON;
SET IDENTITY_INSERT dbo.Usuario OFF;

-- ---------- Tiquetes ----------
SET IDENTITY_INSERT dbo.Ticket ON;
SET IDENTITY_INSERT dbo.Ticket OFF;

-- ---------- Historial de estados ----------
SET IDENTITY_INSERT dbo.HistorialEstado ON;
SET IDENTITY_INSERT dbo.HistorialEstado OFF;

-- ---------- Conversaciones ----------
SET IDENTITY_INSERT dbo.Comentario ON;
SET IDENTITY_INSERT dbo.Comentario OFF;

-- ---------- Auditoría ----------
SET IDENTITY_INSERT dbo.Auditoria ON;
SET IDENTITY_INSERT dbo.Auditoria OFF;

COMMIT TRANSACTION;

-- ---------- Resumen ----------
SELECT INS.Siglas, PLA.Nombre AS [Plan],
       (SELECT COUNT(*) FROM dbo.Usuario U WHERE U.InstitucionId = INS.InstitucionId) AS Usuarios,
       (SELECT COUNT(*) FROM dbo.Ticket T WHERE T.InstitucionId = INS.InstitucionId) AS Tiquetes,
       (SELECT COUNT(*) FROM dbo.Ticket T INNER JOIN dbo.EstadoTicket E ON E.EstadoId = T.EstadoId
         WHERE T.InstitucionId = INS.InstitucionId AND E.EsFinal = 0) AS Abiertos,
       (SELECT COUNT(*) FROM dbo.Auditoria A WHERE A.InstitucionId = INS.InstitucionId) AS FilasAuditoria
FROM dbo.Institucion INS INNER JOIN dbo.PlanSuscripcion PLA ON PLA.PlanId = INS.PlanId;

-- Cuentas de prueba (contraseña: Clave123)
SELECT INS.Siglas, ROL.Nombre AS Rol, USR.Nombre + ' ' + USR.Apellidos AS Nombre, USR.Correo
FROM dbo.Usuario USR
INNER JOIN dbo.Institucion INS ON INS.InstitucionId = USR.InstitucionId
INNER JOIN dbo.Rol ROL ON ROL.RolId = USR.RolId
WHERE USR.Correo LIKE 'admin@%' OR USR.Correo LIKE 'soporte@%' OR USR.Correo LIKE 'profesor@%' OR USR.Correo LIKE 'estudiante@%'
ORDER BY INS.InstitucionId, USR.RolId DESC;
GO
